using System.Collections.Generic;
using System.IO;
using System.Linq;
using BloomGarden.Core.Json;
using BloomGarden.Core.Levels;
using BloomGarden.Core.Model;
using BloomGarden.Solvers;
using NUnit.Framework;

namespace BloomGarden.Tests
{
    /// <summary>
    /// P7-01: MVP2 candidate levels (Assets/_BloomGarden/LevelsCandidates, generated by
    /// Tools/python/generate_trap_candidates.py) are re-checked by the game's own C# solver and analyzer:
    /// valid, solvable, reference solution replays to a win, and real traps exactly as the Python analysis found.
    /// They are not in the shipped catalog (decision D-107).
    /// </summary>
    public class CandidateLevelTests
    {
        private static string Folder => Path.Combine(TestLevels.ProjectRoot, "Assets", "_BloomGarden", "LevelsCandidates");

        private static IEnumerable<(LevelDefinition level, Dictionary<string, object> analysis)> Candidates()
        {
            foreach (string path in Directory.GetFiles(Folder, "BG2-*.json").OrderBy(p => p, System.StringComparer.Ordinal))
            {
                string json = File.ReadAllText(path);
                Assert.IsTrue(LevelLoader.TryLoad(json, out LevelDefinition level, out ValidationResult result), Path.GetFileName(path) + ": " + result);
                var root = (Dictionary<string, object>)MiniJson.Parse(json);
                yield return (level, (Dictionary<string, object>)root["analysis"]);
            }
        }

        [Test]
        public void Candidates_AreSolvable_AndContainRealTraps()
        {
            int count = 0;
            foreach (var (level, analysis) in Candidates())
            {
                count++;
                SolveResult solve = LevelSolver.Solve(level);
                Assert.AreEqual(SolverStatus.Solvable, solve.Status, level.Id);
                Assert.AreEqual((int)(long)analysis["shortestMoves"], solve.ShortestMoves, level.Id + " shortest");
                CollectionAssert.AreEqual(level.ReferenceSolution, solve.SolutionLanes, level.Id + " same solution as Python");
                Assert.IsTrue(LevelSolver.ReplayWins(level, level.ReferenceSolution), level.Id + " replay");

                LevelAnalysis a = LevelAnalyzer.Analyze(level);
                Assert.IsTrue(a.Complete, level.Id);
                Assert.IsFalse(a.IsTrivial, level.Id + " must contain traps");
                Assert.AreEqual((int)(long)analysis["losingMoves"], a.LosingMoves, level.Id + " losing moves");
                Assert.AreEqual((int)(long)analysis["deadlockStates"], a.DeadlockStates, level.Id + " deadlocks");
                Assert.AreEqual(false, analysis["reviewed"], level.Id + " must stay unreviewed until a human checks it");
            }
            Assert.AreEqual(30, count, "30 candidates expected");
        }

        [Test]
        public void Candidates_AreNotShippedInTheMvp1Catalog()
        {
            string levels = Path.Combine(TestLevels.ProjectRoot, "Assets", "_BloomGarden", "Levels");
            Assert.IsEmpty(Directory.GetFiles(levels, "BG2-*.json"), "MVP2 candidates must not be in the shipped levels folder");
        }
    }
}
